import java.util.*; public class NQueens{static List<List<String>>res=new ArrayList<>();static void bt(int n,int row,int[]q){if(row==n){List<String>b=new ArrayList<>();for(int r=0;r<n;r++){char[]arr=new char[n];Arrays.fill(arr,'.');arr[q[r]]='Q';b.add(new String(arr));}res.add(b);return;}for(int c=0;c<n;c++){boolean ok=true;for(int r=0;r<row;r++)if(q[r]==c||Math.abs(q[r]-c)==Math.abs(r-row))ok=false;if(ok){q[row]=c;bt(n,row+1,q);}}}public static void main(String[]a){bt(4,0,new int[4]);System.out.println(res);}}